package com.apixenglish.center.modules.learningreport.repository;import com.apixenglish.center.modules.learningreport.entity.StudentLearningReport;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.UUID;
public interface LearningReportRepository extends JpaRepository<StudentLearningReport,UUID>{@Query("select r from StudentLearningReport r where r.deletedAt is null and (:classId is null or r.clazz.id=:classId) and (:studentId is null or r.student.id=:studentId)")Page<StudentLearningReport> search(@Param("classId")UUID classId,@Param("studentId")UUID studentId,Pageable pageable);}
